import{c as t,Z as o,Q as s,j as r,m as a,o as n}from"./chunks/framework.DVSyX6JR.js";const k=JSON.parse('{"title":"MeshCoreNG CLI App","description":"","frontmatter":{},"headers":[],"relativePath":"docs/cli-app.md","filePath":"docs/cli-app.md"}'),l={name:"docs/cli-app.md"};function d(h,e,p,c,u,m){const i=o("CliAppReleases");return s(),r("div",null,[e[0]||(e[0]=a('<h1 id="meshcoreng-cli-app" tabindex="-1">MeshCoreNG CLI App <a class="header-anchor" href="#meshcoreng-cli-app" aria-label="Permalink to &quot;MeshCoreNG CLI App&quot;">​</a></h1><p>The MeshCoreNG CLI App is a Flutter-based console application for interacting with MeshCoreNG repeaters. It runs on Android, Linux, and Windows.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>The app connects to a MeshCoreNG repeater and gives you a full command interface — either locally over USB/BLE/TCP, or remotely via the mesh network.</p><p><strong>Companion mode</strong> — connect to your local repeater as a serial companion (BLE, USB serial, or TCP):</p><ul><li>Send CLI commands directly to the repeater</li><li>View real-time output</li></ul><p><strong>Remote repeater CLI</strong> — reach any repeater in your mesh network:</p><ul><li>Query stats, change settings, and reboot repeaters that are physically out of reach</li><li>All traffic is relayed over the existing LoRa mesh</li></ul><p><strong>Direct repeater terminal</strong> (<code>-r</code> mode) — connect directly as a repeater peer instead of as a companion:</p><ul><li>Useful for initial setup (no companion needed)</li><li>Required for configuring the TCP bridge (<code>set bridge.*</code>, <code>set wifi.*</code>)</li></ul><h2 id="platforms" tabindex="-1">Platforms <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;Platforms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Format</th></tr></thead><tbody><tr><td>Android</td><td>APK (arm64, arm32, x86_64)</td></tr><tr><td>Linux</td><td>tar.gz (x64)</td></tr><tr><td>Windows</td><td>zip (x64)</td></tr></tbody></table><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><p>Releases are built automatically from the <a href="https://github.com/MichTronics/MeshCoreNG-cli-app" target="_blank" rel="noreferrer">MeshCoreNG-cli-app</a> repository. Click a platform below to download.</p>',14)),n(i),e[1]||(e[1]=a(`<h2 id="android-installation" tabindex="-1">Android installation <a class="header-anchor" href="#android-installation" aria-label="Permalink to &quot;Android installation&quot;">​</a></h2><p>Android APKs are distributed outside the Play Store. You need to enable <strong>Install from unknown sources</strong> for your browser or file manager before installing.</p><ol><li>Download the APK for your device: <ul><li><strong>arm64</strong> — most modern Android phones (2016 and later)</li><li><strong>arm32</strong> — older or 32-bit-only Android devices</li><li><strong>x86_64</strong> — Android emulators or x86 tablets</li></ul></li><li>Open the APK from your downloads folder and follow the installation prompt.</li></ol><h2 id="linux-installation" tabindex="-1">Linux installation <a class="header-anchor" href="#linux-installation" aria-label="Permalink to &quot;Linux installation&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meshcli-ng-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-linux-x64.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meshcli-ng-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-linux-x64/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./meshcli-ng</span></span></code></pre></div><p>USB serial access requires your user to be in the <code>dialout</code> group:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dialout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $USER</span></span></code></pre></div><p>Log out and back in for the group change to take effect.</p><h2 id="windows-installation" tabindex="-1">Windows installation <a class="header-anchor" href="#windows-installation" aria-label="Permalink to &quot;Windows installation&quot;">​</a></h2><ol><li>Extract the zip file.</li><li>Run <code>meshcli-ng.exe</code> from the extracted folder.</li></ol><p>For USB serial you may need a CP210x or CH340 driver depending on your device.</p><h2 id="source-code" tabindex="-1">Source code <a class="header-anchor" href="#source-code" aria-label="Permalink to &quot;Source code&quot;">​</a></h2><p><a href="https://github.com/MichTronics/MeshCoreNG-cli-app" target="_blank" rel="noreferrer">github.com/MichTronics/MeshCoreNG-cli-app</a></p>`,13))])}const b=t(l,[["render",d]]);export{k as __pageData,b as default};
